import sys

def highest_set_bit_position(n):
    """Find the position of the highest set bit (1-indexed) in n."""
    if n == 0:
        return 0
    position = 0
    while n > 1:
        n >>= 1
        position += 1
    return position + 1

def main():
    a = int(sys.stdin.read())
    print(highest_set_bit_position(a))

if __name__ == "__main__":
    main()
"}

