def knapsack(capacity, items):
    """Unbounded knapsack: maximize profit given capacity and items.
    Each item has (value, weight) where value = profit per item, weight = 1.
    We can take up to count items of each type.
    """
    dp = [0] * (capacity + 1)
    for value, weight, count in items:
        for w in range(weight, capacity + 1):
            for take in range(1, count + 1):
                if w - take * weight >= 0:
                    dp[w] = max(dp[w], dp[w - take * weight] + take * value)
    return dp[capacity]

def solve():
    n, m, k = map(int, input().split())
    planets = []

    for _ in range(n):
        name = input().strip()
        planet = {}
        planet['name'] = name
        planet['items'] = []

        for _ in range(m):
            a, b, c = map(int, input().split())
            planet['items'].append((a, b, c))  # (buy_cost, sell_price, max_available)

        planets.append(planet)

    max_profit = 0

    # Try all pairs of planets
    for i in range(n):
        for j in range(n):
            if i == j:
                continue

            # Create items for knapsack: (profit_per_item, weight, max_count)
            items = []
            for buy_cost, sell_price, max_available in planets[i]['items']:
                # Buy on planet i, sell on planet j
                profit = sell_price - buy_cost
                if profit > 0:
                    items.append((profit, 1, min(max_available, k)))

            profit = knapsack(k, items)
            max_profit = max(max_profit, profit)

    print(max_profit)

solve()
"}

