def solve():
    n, m = map(int, input().split())

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        parts = list(map(int, input().split()))
        ci = parts[0]
        neighbors = parts[1:1 + ci]
        graph[i] = neighbors

    s = int(input())

    # Find terminal vertices (no outgoing edges)
    terminal = set()
    for i in range(1, n + 1):
        if not graph[i]:
            terminal.add(i)

    # For each vertex, find minimum distance to terminal
    # and whether it can reach a cycle
    distance = [-1] * (n + 1)
    has_cycle = [False] * (n + 1)

    # BFS from terminal vertices
    from collections import deque

    for term in terminal:
        distance[term] = 0
        queue = deque([term])
        while queue:
            v = queue.popleft()
            for u in graph[v]:
                if distance[u] == -1:
                    distance[u] = distance[v] + 1
                    queue.append(u)
                # Check for cycles
                if distance[u] != -1 and distance[u] < distance[v]:
                    has_cycle[u] = True

    # Determine result from starting vertex s
    if distance[s] != -1:
        # Can reach terminal
        if distance[s] % 2 == 1:
            # Petya wins (odd number of moves)
            print("Win")
            path = [s]
            current = s
            while distance[current] > 0:
                for neighbor in graph[current]:
                    if distance[neighbor] == distance[current] - 1:
                        path.append(neighbor)
                        current = neighbor
                        break
            print(' '.join(map(str, path)))
        else:
            # Petya loses (even number of moves, Vasya's turn)
            print("Lose")
    else:
        # Can't reach terminal, check if can reach a cycle
        if has_cycle[s]:
            print("Draw")
        else:
            print("Lose")

