import sys
import heapq

def solve():
    n = int(sys.stdin.readline())
    parent = {}
    c = {}
    children = {}

    for i in range(1, n + 1):
        p_i, c_i = map(int, sys.stdin.readline().split())
        parent[i] = p_i
        c[i] = c_i

        if p_i not in children:
            children[p_i] = []
        children[p_i].append(i)

    # Calculate subtree sizes
    subtree_size = [0] * (n + 1)

    def dfs(v):
        size = 1
        for child in children.get(v, []):
            size += dfs(child)
        subtree_size[v] = size
        return size

    dfs(1)  # Assuming root is 1, but we should find it

    # Find root
    root = 1
    while parent[root] != 0:
        root = parent[root]

    # Use a min-heap to process vertices in order of increasing subtree size
    heap = []
    for i in range(1, n + 1):
        heapq.heappush(heap, (subtree_size[i], i))

    # Assign values in decreasing order
    a = [0] * (n + 1)
    value = n  # Start from n and go down to 1

    while heap:
        _, v = heapq.heappop(heap)
        a[v] = value
        value -= 1

    # Check if the solution is valid
    valid = True
    for i in range(1, n + 1):
        count = 0
        # Count how many values in subtree of i are less than a[i]
        # We can do this with a DFS or BFS
        def count_less_in_subtree(v):
            nonlocal count
            if a[v] < a[i]:
                count += 1
            for child in children.get(v, []):
                count_less_in_subtree(child)
        count_less_in_subtree(i)

        if count != c[i]:
            valid = False
            break

    if valid:
        print("YES")
        print(" ".join(map(str, a[1:n+1])))
    else:
        print("NO")

if __name__ == "__main__":
    solve()
"}

