def move_time(from_c, to_c):
    if from_c == to_c:
        return 0
    if from_c == 1 and to_c == 2:
        return 1
    if from_c == 1 and to_c == 3:
        return 2
    if from_c == 2 and to_c == 1:
        return 2
    if from_c == 2 and to_c == 3:
        return 1
    if from_c == 3 and to_c == 1:
        return 1
    if from_c == 3 and to_c == 2:
        return 2
    return float('inf')

def solve():
    n = int(input())
    computers = list(map(int, input().split()))

    # Build graph
    graph = [[] for _ in range(n)]
    in_degree = [0] * n

    for i in range(n):
        parts = list(map(int, input().split()))
        k = parts[0]
        dependencies = parts[1:]

        for dep in dependencies:
            graph[dep - 1].append(i)
            in_degree[i] += 1

    # Topological sort
    top_order = []
    queue = [i for i in range(n) if in_degree[i] == 0]

    while queue:
        u = queue.pop(0)
        top_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[part][computer] = minimum time to complete all parts from this part onwards
    INF = float('inf')
    dp = [[INF] * 4 for _ in range(n)]  # computer 1, 2, 3

    for part in top_order:
        comp = computers[part]

        # Try starting at each computer
        for start in range(1, 4):
            # Time to move from start to current computer
            move_time = move_time(start, comp)

            # Time to complete this part
            time = move_time + 1

            # Add time for dependencies
            for dep in graph[part]:
                time += dp[dep][comp]

            dp[part][start] = min(dp[part][start], time)

    # Answer is minimum time starting from any computer
    print(min(dp[0][1], dp[0][2], dp[0][3]))

