import sys

def is_palindrome(s, i, j):
    """Check if substring s[i:j+1] is a palindrome."""
    while i < j:
        if s[i] != s[j]:
            return False
        i += 1
        j -= 1
    return True

def solve(s):
    n = len(s)
    # dp[i][j] will store the palindromic characteristics for substring s[i:j+1]
    # dp[i][j][k] = number of k-palindromes in substring s[i:j+1]
    dp = [[[0] * (n + 1) for _ in range(n)] for _ in range(n)]

    # Base case: single character substrings
    for i in range(n):
        dp[i][i][1] = 1

    # Fill the DP table for substrings of length 2 to n
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # Check if the substring is a palindrome
            if is_palindrome(s, i, j):
                dp[i][j][1] = 1

            # Check for k-palindromes where k > 1
            for k in range(2, n + 1):
                # Left half and right half
                half_len = length // 2
                left_i = i
                left_j = i + half_len - 1
                right_i = j - half_len + 1
                right_j = j

                # Check if left half equals right half
                if s[left_i:left_j+1] == s[right_i:right_j+1]:
                    # Check if both halves are (k-1)-palindromes
                    if dp[left_i][left_j][k-1] > 0 and dp[right_i][right_j][k-1] > 0:
                        dp[i][j][k] = 1

    # Count total k-palindromes for each k
    result = [0] * (n + 1)
    for i in range(n):
        for j in range(i, n):
            for k in range(1, n + 1):
                result[k] += dp[i][j][k]

    return result[1:n+1]

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    result = solve(s)
    print(" ".join(map(str, result)))
