import sys
from functools import lru_cache

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    mod = int(data[2])

    # Read the first m rows
    rows = []
    idx = 3
    for _ in range(m):
        row = data[idx]
        idx += 1
        rows.append(row)

    # Check if the given rows are valid
    col_ones = [0] * n
    for i in range(m):
        for j in range(n):
            if rows[i][j] == '1':
                col_ones[j] += 1

    # Check if any column has more than 2 ones
    for count in col_ones:
        if count > 2:
            print(0)
            return

    # Check if any row has not exactly 2 ones
    for row in rows:
        if row.count('1') != 2:
            print(0)
            return

    # Calculate remaining capacity for each column
    remaining = [2 - count for count in col_ones]

    # Now we need to fill (n - m) rows, each with exactly 2 ones,
    # such that we don't exceed the remaining capacity in any column

    # Use DP to count the number of ways
    @lru_cache(maxsize=None)
    def dp(remaining_rows, col_capacity):
        # col_capacity is a tuple of remaining capacities
        if remaining_rows == 0:
            # Check if all capacities are 0
            return 1 if all(cap == 0 for cap in col_capacity) else 0

        total = 0
        # Try all ways to choose 2 columns for this row
        for i in range(n):
            for j in range(i + 1, n):
                # Place a one in column i and column j
                if col_capacity[i] > 0 and col_capacity[j] > 0:
                    new_capacity = list(col_capacity)
                    new_capacity[i] -= 1
                    new_capacity[j] -= 1
                    total += dp(remaining_rows - 1, tuple(new_capacity))

        return total % mod

    result = dp(n - m, tuple(remaining))
    print(result)

if __name__ == "__main__":
    solve()
