def max_xor(nums):
    # Build trie
    trie = {}
    for num in nums:
        node = trie
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]

    # Find maximum XOR
    max_xor = 0
    for num in nums:
        node = trie
        current_xor = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            # Try to take the opposite bit
            if 1 - bit in node:
                current_xor |= (1 << i)
                node = node[1 - bit]
            else:
                node = node[bit]
        max_xor = max(max_xor, current_xor)

