import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Read the grid
    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # For each intersection (i, j), find the minimum x
    result = []
    for i in range(n):
        row_result = []
        for j in range(m):
            # Collect all skyscrapers on the i-th street and j-th street
            skyscrapers = []
            for k in range(n):
                skyscrapers.append((grid[k][j], k, j))  # (value, row, col)
            for k in range(m):
                skyscrapers.append((grid[i][k], i, k))

            # Remove duplicates (we only need distinct values)
            unique_values = set()
            for val, _, _ in skyscrapers:
                unique_values.add(val)

            # Find the minimum x
            # x is at least the number of distinct values
            x = len(unique_values)

            # But we might need more if we have chains of comparisons
            # We need to find the longest chain of comparisons that must be preserved
            # This is essentially finding the longest path in a DAG

            # Build a graph of comparisons
            graph = {}
            for val, _, _ in skyscrapers:
                graph[val] = set()

            # Add edges based on relative order within each street
            for k in range(n):
                # i-th street
                for l in range(n):
                    if k != l:
                        val1 = grid[k][j]
                        val2 = grid[l][j]
                        if val1 < val2:
                            graph[val1].add(val2)
                        elif val1 > val2:
                            graph[val2].add(val1)

            for k in range(m):
                # j-th street
                for l in range(m):
                    if k != l:
                        val1 = grid[i][k]
                        val2 = grid[i][l]
                        if val1 < val2:
                            graph[val1].add(val2)
                        elif val1 > val2:
                            graph[val2].add(val1)

            # Find longest path (topological sort)
            # We can use BFS for shortest path, but we need longest path
            # So we'll use topological sort and dynamic programming

            # Convert to adjacency list
            adj = {}
            for val in graph:
                adj[val] = list(graph[val])

            # Topological sort using Kahn's algorithm
            in_degree = {val: 0 for val in graph}
            for val in graph:
                for neighbor in graph[val]:
                    in_degree[neighbor] += 1

            queue = [val for val in graph if in_degree[val] == 0]
            topo_order = []
            while queue:
                val = queue.pop(0)
                topo_order.append(val)
                for neighbor in graph[val]:
                    in_degree[neighbor] -= 1
                    if in_degree[neighbor] == 0:
                        queue.append(neighbor)

            # If we have a cycle, we need to handle it
            # But with distinct values, there shouldn't be cycles

            # Longest path from each node
            longest_path = {val: 1 for val in graph}
            for val in topo_order:
                for neighbor in graph[val]:
                    longest_path[neighbor] = max(longest_path[neighbor], longest_path[val] + 1)

            x = max(longest_path.values())
