def parse_projects(input_lines):
    projects = {}
    i = 0
    while i < len(input_lines):
        line = input_lines[i].strip()
        if not line:
            i += 1
            continue

        # Parse project name and version
        name, version = line.split()
        version = int(version)
        projects[name] = projects.get(name, [])
        projects[name].append((version, []))

        # Parse dependencies
        i += 1
        while i < len(input_lines) and input_lines[i].strip() != "":
            line = input_lines[i].strip()
            dep_name, dep_version = line.split()
            dep_version = int(dep_version)
            projects[name][-1][1].append((dep_name, dep_version))
            i += 1

        # Skip empty line
        if i < len(input_lines) and input_lines[i].strip() == "":
            i += 1

    return projects


def calculate_distances(projects, polycarp_name, polycarp_version):
    # Find Polycarp's project
    for name, versions in projects.items():
        for version, _ in versions:
            if name == polycarp_name and version == polycarp_version:
                polycarp_project = (name, version)
                break
        else:
            continue
        break

    # Build dependency graph
    graph = {}
    for name, versions in projects.items():
        for version, deps in versions:
            graph[(name, version)] = []
            for dep_name, dep_version in deps:
                graph[(name, version)].append((dep_name, dep_version))

    # Calculate distances using BFS
    distances = {}
    from collections import deque

    queue = deque()
    queue.append((polycarp_project, 0))
    distances[polycarp_project] = 0

    while queue:
        (current_name, current_version), dist = queue.popleft()

        for dep_name, dep_version in graph[(current_name, current_version)]:
            dep_project = (dep_name, dep_version)
            if dep_project not in distances:
                distances[dep_project] = dist + 1
                queue.append((dep_project, dist + 1))

    return distances


def solve():
    input_lines = [line.strip() for line in sys.stdin if line.strip() != ""]
    projects = parse_projects(input_lines)

    # Find Polycarp's project (first one)
    polycarp_name, polycarp_version = input_lines[0].split()
    polycarp_version = int(polycarp_version)

    distances = calculate_distances(projects, polycarp_name, polycarp_version)

    # For each name, find the best version
    best_versions = {}
    for name, versions in projects.items():
        best = None
        for version, _ in versions:
            project = (name, version)
            if project not in distances:
                continue

            if best is None:
                best = (version, distances[project])
            else:
                # Compare distances
                if distances[project] < best[1]:
                    best = (version, distances[project])
                elif distances[project] == best[1]:
                    # Tie, choose newer version
                    if version > best[0]:
                        best = (version, distances[project])

        if best is not None:
            best_versions[name] = best

    # Sort by lexicographical order
    sorted_projects = sorted(best_versions.items())

    # Output
    print(len(sorted_projects))
    for name, (version, _) in sorted_projects:
        print(f"{name} {version}")

if __name__ == "__main__":
