def solve():
    n, m, k = map(int, input().split())
    matrix = []
    for _ in range(n):
        row = list(map(int, input().split()))
        matrix.append(row)

    # dp[i] = maximum sum with remainder i modulo k
    dp = [-1] * k
    dp[0] = 0  # Base case: remainder 0 with sum 0

    for row in matrix:
        # Generate all possible remainders for this row
        # We can select up to floor(m/2) elements
        max_elements = m // 2

        # Generate all possible sums for this row
        possible_sums = {}

        # Try all subsets of size 0 to max_elements
        for size in range(0, max_elements + 1):
            # Generate all combinations of size elements
            from itertools import combinations
            for indices in combinations(range(m), size):
                total = sum(row[i] for i in indices)
                rem = total % k
                if rem not in possible_sums or total > possible_sums[rem]:
                    possible_sums[rem] = total

        # Now combine with previous dp
        new_dp = [-1] * k
        for i in range(k):
            if dp[i] == -1:
                continue
            for rem, val in possible_sums.items():
                new_rem = (i + rem) % k
                new_sum = dp[i] + val
                if new_dp[new_rem] == -1 or new_sum > new_dp[new_rem]:
                    new_dp[new_rem] = new_sum

        dp = new_dp

    # The answer is the maximum sum with remainder 0
    print(dp[0] if dp[0] != -1 else 0)

solve()
