def solve():
    n, m, k = map(int, input().split())
    matrix = []
    for _ in range(n):
        row = list(map(int, input().split()))
        matrix.append(row)

    # dp[i] = maximum sum with remainder i modulo k
    dp = [-1] * k
    dp[0] = 0  # Base case: remainder 0 with sum 0

    for row in matrix:
        # For this row, we'll find the best remainders for different sizes
        # Create a DP array for this row: dp_row[size][rem] = max sum
        dp_row = [[-1] * k for _ in range(m // 2 + 1)]
        max_elements = m // 2

        # Base case: selecting 0 elements
        dp_row[0][0] = 0

        # For each possible number of elements we can select
        for size in range(1, max_elements + 1):
            # We can add one more element to a selection of size-1
            for prev_size in range(size):
                for prev_rem in range(k):
                    if dp_row[prev_size][prev_rem] == -1:
                        continue
                    # Try adding each element
                    for i in range(m):
                        new_total = dp_row[prev_size][prev_rem] + row[i]
                        new_rem = new_total % k
                        if new_total > dp_row[size][new_rem]:
                            dp_row[size][new_rem] = new_total

        # Now combine with previous dp
        new_dp = [-1] * k
        for prev_size in range(max_elements + 1):
            for prev_rem in range(k):
                if dp_row[prev_size][prev_rem] == -1:
                    continue
                for i in range(k):
                    if dp[i] == -1:
                        continue
                    new_rem = (prev_rem + i) % k
                    new_sum = dp_row[prev_size][prev_rem] + dp[i]
                    if new_dp[new_rem] == -1 or new_sum > new_dp[new_rem]:
                        new_dp[new_rem] = new_sum

        dp = new_dp

    # The answer is the maximum sum with remainder 0
    print(dp[0] if dp[0] != -1 else 0)

solve()
