from collections import deque, defaultdict

def solve():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    for i in range(1, n + 1):
        parts = list(map(int, input().split()))
        ci = parts[0]
        if ci > 0:
            graph[i] = parts[1:]

    s = int(input())

    # Find terminal vertices (no outgoing edges)
    terminal = []
    for i in range(1, n + 1):
        if i not in graph:
            terminal.append(i)

    # BFS to find shortest paths from s
    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[s] = 0
    prev = {i: None for i in range(1, n + 1)}

    q = deque([s])
    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] > dist[u] + 1:
                dist[v] = dist[u] + 1
                prev[v] = u
                q.append(v)

    # Check if Petya can win
    win = False
    winning_path = []
    for t in terminal:
        if dist[t] != float('inf') and dist[t] % 2 == 1:
            win = True
            # Reconstruct path
            path = []
            current = t
            while current is not None:
                path.append(current)
                current = prev[current]
            winning_path = path[::-1]
            break

    # Check if there's a cycle (draw)
    visited = set()
    in_queue = set()
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        if u in visited:
            return
        if u in in_queue:
            has_cycle = True
            return
        in_queue.add(u)
        for v in graph[u]:
            dfs(v)
        visited.add(u)
        in_queue.remove(u)

    dfs(s)

    if win:
        print("Win")
        print(' '.join(map(str, winning_path)))
    elif has_cycle:
        print("Draw")
    else:
        print("Lose")

solve()
