    # Try to build a number that is divisible by 7
    def backtrack(pos, remainder, current):
        if pos == n:
            if remainder == 0:
                return current
            return None

        # Try to place a digit at the current position
        for i in range(n):
            if used[i]:
                continue

            # Skip leading zeroes
            if pos == 0 and a[i] == '0':
                continue

            used[i] = True
            new_remainder = (remainder * 10 + int(a[i])) % 7
            result = backtrack(pos + 1, new_remainder, current + a[i])

            if result is not None:
                return result

            used[i] = False

        return None

    result = backtrack(0, 0, "")
    print(result if result else "0")

