from collections import deque, defaultdict

def solve():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    for i in range(1, n + 1):
        parts = list(map(int, input().split()))
        ci = parts[0]
        if ci > 0:
            graph[i] = parts[1:]

    s = int(input())

    # BFS to find shortest path to each vertex
    dist = [-1] * (n + 1)
    dist[s] = 0
    q = deque([s])

    while q:
        u = q.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)

    # Check for win
    win_path = []
    for v in range(1, n + 1):
        if dist[v] != -1 and len(graph[v]) == 0 and dist[v] % 2 == 1:
            # Found a winning path
            path = []
            current = v
            while current != s:
                path.append(current)
                # Find predecessor
                for u in graph:
                    if current in graph[u]:
                        current = u
                        break
            path.append(s)
            path.reverse()
            win_path = path
            break

    if win_path:
        print("Win")
        print(' '.join(map(str, win_path)))
        return

    # Check for draw (cycle reachable from s)
    visited = set()
    for v in range(1, n + 1):
        if dist[v] != -1 and v not in visited:
            # DFS to check for cycle
            def has_cycle(node, path_set):
                if node in path_set:
                    return True
                if node in visited:
                    return False
                visited.add(node)
                path_set.add(node)
                for neighbor in graph[node]:
                    if has_cycle(neighbor, path_set):
                        return True
                path_set.remove(node)
                return False

            if has_cycle(v, set()):
                print("Draw")
                return

    print("Lose")

