def can_form_tree(ci_values, n):
    """Check if we can form a valid tree with the given subtree sizes."""

    # If there's only one node, it must be a leaf
    if n == 1:
        return ci_values[0] == 1

    # Check if we can partition the nodes into valid subtrees
    for i in range(n):
        # Skip if this node is a leaf
        if ci_values[i] == 1:
            continue

        # This node is an internal node with subtree size ci_values[i]
        # We need at least two children whose subtree sizes sum to ci_values[i] - 1
        remaining_sum = ci_values[i] - 1

        # Try to find two subtrees that sum to remaining_sum
        found = False

        # Try all pairs of nodes (excluding i)
        for j in range(n):
            if j == i:
                continue

            # First child
            if ci_values[j] == 1:
                # Leaf child
                if remaining_sum == 1:
                    # Check if we can form a valid tree with the remaining nodes
                    # Remove i and j from consideration
                    new_ci = [ci_values[k] for k in range(n) if k != i and k != j]
                    if can_form_tree(new_ci, n - 2):
                        found = True
                        break
            else:
                # Internal node child
                # Check if we can form a valid tree with the remaining nodes
                # We need to find a second child for this internal node
                for k in range(n):
                    if k == i or k == j:
