    dp = [[0] * n for _ in range(n)]

    # Check all substrings
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            substr = s[i:j+1]

            # Check if it's a palindrome
            is_palindrome = substr == substr[::-1]
            if is_palindrome:
                # Check if it's a k-palindrome for k > 1
                if length > 1:
                    half_len = length // 2
                    left = substr[:half_len]
                    right = substr[half_len:]

                    if left == right:
                        # Both halves must be (k-1)-palindromes
                        k_left = dp[i][i + half_len - 1]
                        k_right = dp[i + half_len][j]

                        if k_left > 0 and k_right > 0:
                            k = min(k_left, k_right) + 1
                            dp[i][j] = k
                        else:
                            # At least one half is not a palindrome
                            dp[i][j] = 1
                    else:
                        # Not a k-palindrome for k > 1
                        dp[i][j] = 1
                else:
                    # Single character is always a 1-palindrome
                    dp[i][j] = 1
            else:
                # Not a palindrome
                dp[i][j] = 0

    # Count how many substrings are k-palindromes for each k
    result = [0] * n
    for i in range(n):
        for j in range(n):
            k = dp[i][j]
            if k > 0:
                result[k - 1] += 1

    print(' '.join(map(str, result)))
