    # Track count of likes and first occurrence of each count
    count = {}
    first_occurrence = {}

    for i, photo_id in enumerate(likes, 1):
        count[photo_id] = count.get(photo_id, 0) + 1

        # Track first occurrence of this count
        if photo_id not in first_occurrence:
            first_occurrence[photo_id] = {}

        current_count = count[photo_id]
        if current_count not in first_occurrence[photo_id]:
