    # Find the maximum like count
    max_count = max(count.values())

    # Find photos with max_count and their first occurrence of max_count
    candidates = []
    for photo_id, photo_count in count.items():
        if photo_count == max_count:
            candidates.append((first_occurrence[photo_id][max_count], photo_id))

    # Sort by first occurrence and return the winner
    candidates.sort()
    print(candidates[0][1])

