def solve():
    s1 = sys.stdin.readline().strip()
    s2 = sys.stdin.readline().strip()
    virus = sys.stdin.readline().strip()

    # Find all common characters
    common_chars = set(s1) & set(s2)

    # Build the LCS character by character
    lcs = []

    # Try to build the LCS
    for c in common_chars:
        # Check if we can add this character to the LCS
        # without creating the virus
        temp_lcs = lcs + [c]
        if virus not in ''.join(temp_lcs):
            lcs = temp_lcs

    # Check if we can build a longer LCS by trying different orders
    # This is a simple greedy approach that may not work for all cases
    # We need a more sophisticated approach

    # Let's try a different approach: dynamic programming
    # dp[i][j] will store the longest common subsequence of s1[0..i-1] and s2[0..j-1]
    # that doesn't contain the virus

    n, m = len(s1), len(s2)
    dp = [[[] for _ in range(m + 1)] for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            # Case 1: s1[i] == s2[j]
            if s1[i] == s2[j]:
                new_lcs = dp[i][j] + [s1[i]]
                if virus not in ''.join(new_lcs):
                    dp[i+1][j+1] = new_lcs
                else:
                    # We can't use this character
                    pass

            # Case 2: s1[i] != s2[j]
            # Try extending from s1[i-1]
            if dp[i][j+1]:
