def to_base3(n):
    """Convert n to its base-3 representation as a string"""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(str(n % 3))
        n //= 3
    return ''.join(reversed(digits))

def next_good_number(n):
    """Find the smallest good number ≥ n"""
    # Convert to base-3
    base3 = to_base3(n)

    # Find the first '2' from right to left
    pos = -1
    for i in range(len(base3)):
        if base3[i] == '2':
            pos = i
            break

    if pos == -1:
        # No '2' found, n is already good
        return n

    # Carry over
    # Convert to list for easier manipulation
    digits = list(base3)

    # Set the '2' to '0'
    digits[pos] = '0'

    # Carry over to the next higher position
    carry = 1
    for i in range(pos + 1, len(digits)):
        if digits[i] == '2':
            digits[i] = '0'
            carry = 1
        else:
            digits[i] = str(int(digits[i]) + carry)
            carry = 0
            break

    if carry == 1:
        # Need to add a new digit
        digits.append('1')

    # Convert back to integer
    return int(''.join(digits))

q = int(input())
for _ in range(q):
