def solve():
    n = int(input())
    s = input().strip()

    # dp[i][j]: number of ways to split first i digits with last number ending at position j
    # We need to consider positions 0 to n (0-indexed)
    # dp[i][j] means we have split up to position i, and the last number ends at position j
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: single number from 0 to i
    for i in range(1, n + 1):
        if s[0] != '0':
            dp[i][0] = 1
        else:
            dp[i][0] = 0

    for i in range(2, n + 1):
        # Try to split at position j (0 < j < i)
        for j in range(1, i):
            # Check if s[j:i] is a valid number (no leading zeros)
            if s[j] == '0':
                continue

            # Check all previous splits ending at j
            for k in range(j):
                # Check if s[k:j] < s[j:i]
                if s[k:j] < s[j:i]:
                    dp[i][j] = (dp[i][j] + dp[j][k]) % MOD

    # Sum all ways to split the entire string
    result = sum(dp[n][j] for j in range(n)) % MOD
    print(result)

