        # Create a dictionary to count occurrences of each value
        value_positions = {}
        for idx, val in enumerate(a):
            if val not in value_positions:
                value_positions[val] = []
            value_positions[val].append(idx)

        result = 0

        # For each value x, get all positions where x appears
        for x in value_positions:
            positions = value_positions[x]
            # For each pair (i, k) where i < k and a_i = a_k
            for i in range(len(positions)):
                for k in range(i + 1, len(positions)):
                    # i < k and a_i = a_k
                    # Count how many positions j exist between i and k
                    # and how many positions l exist after k where a_l = a_j
                    # Actually, we need to count for each j between i and k,
                    # how many l > k exist such that a_l = a_j

                    # Get the positions between i and k
                    start = positions[i] + 1
                    end = positions[k] - 1

                    # Count how many l > positions[k] exist for each j between i and k
                    for j in range(start, end + 1):
                        target_value = a[j]
                        # Count how many l > positions[k] have value target_value
                        count_l = 0
                        for l in range(positions[k] + 1, n):
                            if a[l] == target_value:
                                count_l += 1
                        result += count_l

        print(result)

