def factorial(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def solve():
    n, h = map(int, input().split())
    a = list(map(int, input().split()))

    # Calculate the difference array
    diff = [0] * (n + 1)
    diff[1] = h - a[0]
    for i in range(1, n):
        diff[i + 1] = a[i - 1] - a[i]

    mod = 1000000007

    # Calculate the product of factorials of absolute values of differences
    result = 1
    for i in range(1, n + 1):
        if diff[i] != 0:
            result = (result * factorial(abs(diff[i]), mod)) % mod

    print(result)

