    """Addition modulo mod"""
    return (a + b) % mod

def mod_mul(a, b, mod):
    """Multiplication modulo mod"""
    return (a * b) % mod

def mod_div(a, b, mod):
    """Division modulo mod (a/b mod mod)"""
    return mod_mul(a, modinv(b, mod), mod)

