import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    size = 1 << n

    # Initialize array
    a = [int(next(it)) for _ in range(size)]

    # Segment tree
    tree = [[] for _ in range(4 * size)]

    def build(node, start, end):
        if start == end:
            tree[node] = [a[start - 1]]
        else:
            mid = (start + end) // 2
            build(2 * node, start, mid)
            build(2 * node + 1, mid + 1, end)
            tree[node] = tree[2 * node] + tree[2 * node + 1]

    build(1, 1, size)

    def apply_reverse(node, k):
        # Reverse blocks of size 2^k
        # We need to reverse segments of length exactly 2^k
        if len(tree[node]) == 1:
            return
        block_size = 1 << k
        if len(tree[node]) == block_size:
            tree[node] = tree[node][::-1]
        else:
            mid = (len(tree[node]) + 1) // 2
            apply_reverse(2 * node, k)
            apply_reverse(2 * node + 1, k)

    def apply_swap(node, k):
        # Swap blocks of size 2^(k+1)
        # We need to swap adjacent segments of length exactly 2^(k+1)
        if len(tree[node]) == 1:
            return
        block_size = 1 << (k + 1)
        if len(tree[node]) == block_size:
            # Swap with sibling
            tree[node] = tree[2 * node + 1] + tree[2 * node]
        else:
            mid = (len(tree[node]) + 1) // 2
            apply_swap(2 * node, k)
            apply_swap(2 * node + 1, k)

    def update(x, val):
        # Point update
        def update_helper(node, start, end):
            if start == end:
                tree[node] = [val]
            else:
                mid = (start + end) // 2
                if x <= mid:
                    update_helper(2 * node, start, mid)
                else:
                    update_helper(2 * node + 1, mid + 1, end)
        update_helper(1, 1, size)

    def query_sum(l, r):
        # Range sum query
        def query_helper(node, start, end):
            if r < start or l > end:
                return 0
            if l <= start and end <= r:
                return sum(tree[node])
            mid = (start + end) // 2
            return query_helper(2 * node, start, mid) + query_helper(2 * node + 1, mid + 1, end)
        return query_helper(1, 1, size)

    for _ in range(q):
        cmd = next(it)
        if cmd == '1':
            x = int(next(it))
            k = int(next(it))
            update(x, k)
        elif cmd == '2':
            k = int(next(it))
            apply_reverse(1, k)
        elif cmd == '3':
