def comb(n, k, mod):
    """Compute combination C(n, k) modulo mod"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    # Use Pascal's triangle for small n
    if n < 1000:
        dp = [0] * (n + 1)
        for i in range(n + 1):
