def longest_common_subsequence_without_virus(s1, s2, virus):
    """Find the longest common subsequence of s1 and s2 that does not contain virus as a contiguous substring."""

    # Standard LCS DP table
    n, m = len(s1), len(s2)
    dp = [[(0, '') for _ in range(m + 1)] for _ in range(n + 1)]  # (length, subsequence)

    # Fill DP table
    for i in range(n):
        for j in range(m):
            if s1[i] == s2[j]:
                # Current characters match, extend the LCS
                length, subseq = dp[i][j]
                dp[i+1][j+1] = (length + 1, subseq + s1[i])
            else:
                # Take max of left or top
                if dp[i][j+1][0] > dp[i+1][j][0]:
                    dp[i+1][j] = dp[i][j+1]
                elif dp[i][j+1][0] == dp[i+1][j][0]:
                    # Tie: choose one with lexicographically smaller subsequence
                    dp[i+1][j] = dp[i][j+1] if dp[i][j+1][1] < dp[i+1][j][1] else dp[i+1][j]
                else:
                    dp[i+1][j] = dp[i+1][j]

    # Reconstruct the LCS
    length, subseq = dp[n][m]

    # Check if the LCS contains virus as a contiguous substring
    virus_len = len(virus)
    if virus_len > len(subseq):
        return subseq  # Can't contain virus

    # Check all contiguous substrings of length virus_len
    for i in range(len(subseq) - virus_len + 1):
        if subseq[i:i+virus_len] == virus:
            # Contains virus, need to find a valid LCS
            # This is tricky, we need to try different paths
            # Let's try a simpler approach: find all common subsequences and check
            # This might not be efficient for longer strings, but given constraints are small (<= 100), it should work

            # Find all common subsequences using DP
            n, m = len(s1), len(s2)
            all_subseqs = set()

            # DP to generate all subsequences
            dp = [[[] for _ in range(m + 1)] for _ in range(n + 1)]

            for i in range(n):
                for j in range(m):
                    if s1[i] == s2[j]:
                        # Current characters match, extend all subsequences
                        for subseq in dp[i][j]:
                            all_subseqs.add(subseq + s1[i])
                        all_subseqs.add(s1[i])
                    else:
                        # Take all from left or top
                        for subseq in dp[i][j+1]:
                            all_subseqs.add(subseq)
                        for subseq in dp[i+1][j]:
                            all_subseqs.add(subseq)

            # Add empty subsequence
            all_subseqs.add('')

            # Check if any subsequence contains virus as a contiguous substring
            virus_len = len(virus)
            valid_subseqs = []
            for subseq in all_subseqs:
                if virus_len > len(subseq):
                    valid_subseqs.append(subseq)
                else:
                    contains_virus = False
                    for i in range(len(subseq) - virus_len + 1):
                        if subseq[i:i+virus_len] == virus:
                            contains_virus = True
                            break
                    if not contains_virus:
                        valid_subseqs.append(subseq)

            if not valid_subseqs:
                return '0'

            # Return the longest valid subsequence
            valid_subseqs.sort(key=lambda x: -len(x))
            return valid_subseqs[0]

    return subseq

# Read input
