import sys

def solve():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    MOD = 10**9 + 7

    # dp[i] = number of ways to split the first i digits
    dp = [0] * (n + 1)
    dp[0] = 1  # Empty string has 1 way (no split)

    # last[i] = value of the last number in the split ending at position i
    # We'll store a list of tuples: (count, last_number)
    # where count is the number of splits ending at i with that last number
    last = [{} for _ in range(n + 1)]  # Dictionary: last_number -> count

    for i in range(1, n + 1):
        for j in range(i):
            # Consider splitting at position j, then taking s[j:i] as the next number
            if s[j] == '0':
                continue  # Skip if the number has leading zero

            # Convert substring to integer
            num = int(s[j:i])

            # Check if this number is greater than the last number in the split ending at j
            for prev_last, count in last[j].items():
                if num > prev_last:
                    dp[i] = (dp[i] + count) % MOD
                    if num in last[i]:
                        last[i][num] = (last[i][num] + count) % MOD
                    else:
                        last[i][num] = count

    print(dp[n])

if __name__ == "__main__":
    solve()

