def apply_reverse(node, k, tree, size):
    """Apply reverse operation to blocks of size 2^k"""
    block_size = 1 << k
    if node.size == block_size:
        # Reverse the block
        for i in range(block_size):
            tree[node.left].val[node.pos[i]] = tree[node.right].val[node.pos[block_size - 1 - i]]
            tree[node.right].val[node.pos[block_size - 1 - i]] = tree[node.left].val[node.pos[i]]
            tree[node.left].val[node.pos[i]] = tree[node.right].val[node.pos[block_size - 1 - i]]
    elif node.size > block_size:
        # Apply to children
        apply_reverse(node.left, k, tree, size)
        apply_reverse(node.right, k, tree, size)


def apply_swap(node, k, tree, size):
    """Apply swap operation to pairs of blocks of size 2^k"""
    block_size = 1 << k
    if node.size == 2 * block_size:
        # Swap the two blocks
        for i in range(block_size):
            tree[node.left].val[node.pos[i]] = tree[node.right].val[node.pos[i]]
            tree[node.right].val[node.pos[i]] = tree[node.left].val[node.pos[i]]
            tree[node.left].val[node.pos[i]] = tree[node.right].val[node.pos[i]]
    elif node.size > 2 * block_size:
        # Apply to children
        apply_swap(node.left, k, tree, size)
        apply_swap(node.right, k, tree, size)


def build_tree(arr, size):
    """Build a segment tree"""
    if size == 1:
        return {'val': arr[0], 'left': None, 'right': None, 'size': 1, 'pos': [0]}
    mid = size // 2
    left = build_tree(arr[:mid], mid)
    right = build_tree(arr[mid:], size - mid)
    return {'val': left['val'] + right['val'], 'left': left, 'right': right, 'size': size, 'pos': list(range(size))}


def update(node, index, value, tree, size):
    """Update a single position"""
    if node['size'] == 1:
        node['val'] = value
        return
    mid = node['size'] // 2
    if index < mid:
        update(node['left'], index, value, tree, mid)
    else:
        update(node['right'], index - mid, value, tree, size - mid)
    node['val'] = node['left']['val'] + node['right']['val']


def query_sum(node, l, r, tree, size):
    """Query sum of subarray [l, r]"""
    if r < node['pos'][0] or l > node['pos'][-1]:
        return 0
    if l <= node['pos'][0] and r >= node['pos'][-1]:
        return node['val']
    return query_sum(node['left'], l, r, tree, node['size'] // 2) + query_sum(node['right'], l, r, tree, size - node['size'] // 2)


