import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    ci = list(map(int, data[1:1+n]))

    # Check if there's exactly one node with ci = n (the root)
    root_count = ci.count(n)
    if root_count != 1:
        print("NO")
        return

    # Check if there's at least one node with ci = 1 (a leaf)
    if ci.count(1) < 1:
        print("NO")
        return

    # Check each node with ci > 1
    for k in ci:
        if k == 1:
            continue

        # Need at least two nodes whose ci values sum to k - 1
        # We can use any two nodes, including the same node twice
        # But we can't use the same node twice because it would mean the node is its own child

        # Let's try all pairs
        found = False
        for i in range(n):
            if ci[i] == 1:
                # Leaf nodes have ci = 1, we can use them
                for j in range(n):
                    if ci[j] == 1 and i != j:
                        # We need two different leaves
                        if ci[i] + ci[j] == k - 1:
                            found = True
