            else:
                # Non-leaf nodes
                for j in range(n):
                    if ci[j] != 1:
                        # Non-leaf nodes
                        if ci[i] + ci[j] == k - 1 and i != j:
                            found = True
                            break

        if not found:
            print("NO")
            return

    print("YES")

