def solve():
    n = int(input())
    a = []
    for _ in range(n):
        row = list(map(float, input().split()))
        a.append(row)

    # dp[mask] = probability that the last fish in mask survives
    dp = [0.0] * (1 << n)

    # Base case: only one fish left
    for i in range(n):
        dp[1 << i] = 1.0

    # Fill dp for all other masks
    for mask in range(1, 1 << n):
        if bin(mask).count('1') == 1:
            continue  # already handled

        # Try all pairs (i, j) that can meet
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            for j in range(n):
                if i == j or not (mask & (1 << j)):
                    continue

                # Fish i and j meet
                # Probability that i eats j
                new_mask = mask ^ (1 << i) ^ (1 << j)
                dp[mask] += a[i][j] * dp[new_mask]

                # Probability that j eats i
                dp[mask] += a[j][i] * dp[new_mask]

    # Output results
    result = [0.0] * n
    for i in range(n):
        result[i] = dp[1 << i]

    print(' '.join(f"{x:.6f}" for x in result))

solve()
