def is_k_palindrome(s, k):
    if k == 1:
        return s == s[::-1]
    n = len(s)
    if n % 2 != 0:
        return False  # Odd length can't be split into equal halves
    half = n // 2
    left = s[:half]
    right = s[half:]
    return left == right and is_k_palindrome(left, k - 1) and is_k_palindrome(right, k - 1)

def solve(s):
    n = len(s)
    result = [0] * n

    # Memoization for is_k_palindrome
    memo = {}

    def memoized_is_k_palindrome(s, k):
        key = (s, k)
        if key in memo:
            return memo[key]

        if k == 1:
            res = s == s[::-1]
        else:
            n = len(s)
            if n % 2 != 0:
                res = False
            else:
                half = n // 2
                left = s[:half]
                right = s[half:]
                res = left == right and memoized_is_k_palindrome(left, k - 1) and memoized_is_k_palindrome(right, k - 1)

        memo[key] = res
        return res

    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            for k in range(1, n + 1):
                if memoized_is_k_palindrome(substring, k):
                    result[k - 1] += 1

    return result

